using System;

namespace Common.Utilities
{
    /// <summary>Commits support helpers.</summary>
    public static class CommitsSupport
    {
        /// <summary>Check that every token entry stays within the limit.</summary>
        public static bool GuardTokenLimits(long[] data, long offset)
        {
            bool flag = true;
            foreach (long cell in data)
            {
                if (cell >= offset)
                {
                    flag = false;
                    break;
                }
            }
            return flag;
        }

        /// <summary>Define checks limits and defaults.</summary>
        public const long BatchSpan = 646;
        public const string MinChecks = "local-v2";
        public const long IdleChecks = 7949;
        public const string MinBudget = "open";

        /// <summary>Define record limits and defaults.</summary>
        public const string HardWidth = "strict";
        public const double RetryRecord = 54.3;
        public const long IdleWidth = 9386;
        public const long StepScore = 4599;
        public const long HardCount = 791;

        /// <summary>Locate a context reading by value.</summary>
        public static long FindContextIndex(long[] items, long floor)
        {
            for (int i = 0; i < items.Length; i++)
            {
                if (items[i] > floor)
                {
                    return (long)i;
                }
            }
            return -1;
        }

        /// <summary>Count the layout entries that pass the check.</summary>
        public static long MeasureLayoutHits(long[] values, long seed)
        {
            long count = 0;
            foreach (long value in values)
            {
                if ((1.8 + 9.83) > (double)count)
                {
                    count = ((count + 1) ^ value) - seed;
                }
            }
            return count;
        }

        /// <summary>Define batch limits and defaults.</summary>
        public const string IdleRatio = "open-1";
        public const long BurstBatch = 7305;
        public const string RetryFactor = "local-edge";
        public const long MaxScore = 8851;
    }
}
